package run.ikaros.password; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/password/items/{itemId}/totp") public class TotpConfigController{private final TotpConfigService service;public TotpConfigController(TotpConfigService s){service=s;}@PutMapping public Mono<TotpConfigView> save(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID itemId,@Valid@RequestBody UpsertTotpRequest r){return service.save(a,itemId,r);}@GetMapping public Mono<TotpConfigView> get(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID itemId){return service.get(a,itemId);}}
